-- Aprenda se Divertindo · 47 · Trilha Policial · lote extra 3 (casos práticos) (100 questões)
-- Rode depois do 46-trilha-policial-2.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":5539,"materia":"pen","nivel":0,"enunciado":"Um rapaz de 17 anos pratica um roubo. Pelo Código Penal, ele é:","opcoes":["Inimputável, sujeito às normas do ECA","Imputável, com pena reduzida pela metade","Imputável, como qualquer adulto que comete crime","Semi-imputável, com pena reduzida de 1/3 a 2/3"],"explicacao":"Menores de 18 anos respondem por ato infracional (art. 27 do CP)."},{"id":5540,"materia":"pen","nivel":1,"enunciado":"Gustavo comprou um celular por R$ 100 sabendo que era produto de roubo. Ele cometeu:","opcoes":["Receptação","Roubo","Furto","Favorecimento pessoal, por ajudar o autor do roubo"],"explicacao":"Adquirir coisa que sabe ser produto de crime é receptação (art. 180 do CP)."},{"id":5541,"materia":"pen","nivel":1,"enunciado":"Para furtar o rádio, Diego quebrou o vidro do carro. Ele cometeu:","opcoes":["Furto qualificado pelo rompimento de obstáculo","Furto simples, pois o vidro não é obstáculo","Roubo, pela violência contra o vidro","Dano e furto simples, em concurso material, pois houve destruição do vidro"],"explicacao":"A violência contra a coisa não transforma o furto em roubo."},{"id":5542,"materia":"pen","nivel":1,"enunciado":"Lucas espalhou, sabendo ser mentira, que o vizinho tinha furtado um carro. Lucas cometeu:","opcoes":["Calúnia","Difamação","Injúria","Denunciação caluniosa, por ter acusado o vizinho"],"explicacao":"Calúnia é imputar falsamente a alguém fato definido como crime."},{"id":5543,"materia":"pen","nivel":1,"enunciado":"Durante uma abordagem, um homem xinga o policial que está em serviço. Ele comete:","opcoes":["Desacato","Desobediência","Resistência","Injúria comum, sem relação com a função pública"],"explicacao":"Desacato é ofender funcionário público no exercício da função ou em razão dela."},{"id":5544,"materia":"pen","nivel":2,"enunciado":"Ao ser preso, o suspeito agride o policial para impedir a prisão. Ele comete:","opcoes":["Resistência","Desobediência","Desacato, apenas","Favorecimento pessoal"],"explicacao":"Na resistência há violência ou ameaça contra o funcionário que executa ato legal."},{"id":5545,"materia":"pen","nivel":2,"enunciado":"Rafael empurrou um colega, sem querer matá-lo. O colega caiu, bateu a cabeça e morreu. Rafael responde por:","opcoes":["Lesão corporal seguida de morte","Homicídio doloso simples","Homicídio culposo, apenas","Tentativa de homicídio qualificado"],"explicacao":"Há dolo na lesão e culpa na morte: crime preterdoloso."},{"id":5546,"materia":"pen","nivel":2,"enunciado":"Pelo WhatsApp, o golpista se passa por filho da vítima e a convence a fazer um Pix para \"pagar uma conta urgente\". Ele comete:","opcoes":["Estelionato com fraude eletrônica, de pena maior","Furto simples","Extorsão","Apropriação indébita, pois a vítima entregou o dinheiro por vontade própria"],"explicacao":"Art. 171, § 2º-A, do CP: pena de reclusão de 4 a 8 anos e multa."},{"id":5547,"materia":"pen","nivel":2,"enunciado":"O caixa de uma loja, que recebia o dinheiro das vendas legitimamente, passou a ficar com parte dele. Ele cometeu:","opcoes":["Apropriação indébita","Furto mediante fraude","Roubo","Estelionato contra a empresa"],"explicacao":"Ele já tinha a posse lícita do dinheiro antes de se apropriar dele."},{"id":5548,"materia":"pen","nivel":2,"enunciado":"Criminosos obrigam a vítima a entrar no carro e a sacar dinheiro em caixas eletrônicos. É o chamado sequestro-relâmpago, que configura:","opcoes":["Extorsão com restrição da liberdade da vítima","Sequestro e cárcere privado, apenas","Furto qualificado","Roubo simples, sem aumento de pena pela restrição da liberdade"],"explicacao":"Art. 158, § 3º, do Código Penal."},{"id":5549,"materia":"pen","nivel":2,"enunciado":"Sob ameaça de morte da própria família, um bancário entrega o dinheiro do cofre a assaltantes. Pela coação moral irresistível:","opcoes":["Só o coator responde pelo crime","O bancário e o coator respondem juntos","Só o bancário responde","Ninguém responde, pois houve coação"],"explicacao":"A coação moral irresistível exclui a culpabilidade do coagido (art. 22 do CP)."},{"id":5550,"materia":"pen","nivel":2,"enunciado":"Pedro matou a vítima logo após ser injustamente provocado por ela, sob o domínio de violenta emoção. É homicídio:","opcoes":["Privilegiado, com redução de 1/6 a 1/3","Qualificado por motivo fútil","Culposo","Simples, sem qualquer redução de pena, pois a emoção não importa"],"explicacao":"Art. 121, § 1º, do Código Penal."},{"id":5551,"materia":"pen","nivel":2,"enunciado":"Durante um protesto, Jonas quebrou intencionalmente o vidro de uma viatura da Polícia Civil. Ele cometeu:","opcoes":["Dano qualificado, por ser patrimônio público","Dano simples, de ação privada","Furto qualificado","Nenhum crime, apenas ilícito civil de reparação do dano"],"explicacao":"Art. 163, parágrafo único, III, do CP."},{"id":5552,"materia":"pen","nivel":3,"enunciado":"Quando a participação no crime é de menor importância, a pena do partícipe:","opcoes":["Pode ser diminuída de 1/6 a 1/3","É igual à do autor, sem diferença","É sempre excluída","É aumentada de metade"],"explicacao":"Art. 29, § 1º, do Código Penal."},{"id":5553,"materia":"pen","nivel":4,"enunciado":"João combinou com Pedro apenas um furto, mas Pedro, durante o crime, matou o vigia. Quanto a João:","opcoes":["Responde pelo furto, com pena aumentada até a metade se o resultado mais grave era previsível","Responde por latrocínio, como Pedro, pois ambos assumiram o risco de qualquer resultado","Não responde por nada","Responde por homicídio qualificado"],"explicacao":"É a cooperação dolosamente distinta (art. 29, § 2º, do CP)."},{"id":5554,"materia":"ppen","nivel":1,"enunciado":"Num crime de ação penal pública condicionada, o delegado só pode instaurar o inquérito:","opcoes":["Com a representação da vítima","De ofício, a qualquer tempo, sem ouvir a vítima","Com ordem do governador","Após a sentença"],"explicacao":"Art. 5º, § 4º, do CPP."},{"id":5555,"materia":"ppen","nivel":2,"enunciado":"Pela Lei 13.245/2016, durante o interrogatório do investigado na delegacia, o advogado:","opcoes":["Pode assistir o cliente, sob pena de nulidade do interrogatório","Nunca pode estar presente","Só pode entrar na sala com ordem judicial expressa e por escrito","Deve sair antes das perguntas"],"explicacao":"Também pode apresentar razões e quesitos."},{"id":5556,"materia":"ppen","nivel":1,"enunciado":"Pela Súmula Vinculante 11, o uso de algemas só é lícito em caso de:","opcoes":["Resistência, fundado receio de fuga ou perigo, justificado por escrito","Qualquer prisão, sempre","Crimes hediondos, apenas","Pedido da vítima ou da imprensa, mesmo sem risco algum à operação"],"explicacao":"O uso indevido pode gerar nulidade da prisão e responsabilidade do agente."},{"id":5557,"materia":"ppen","nivel":2,"enunciado":"Num crime de injúria (ação penal privada), o delegado só pode instaurar inquérito:","opcoes":["A requerimento de quem tenha qualidade para propor a ação","De ofício, sem pedido da vítima, por se tratar de crime contra a honra","Por requisição de qualquer cidadão","Após a condenação do autor"],"explicacao":"Art. 5º, § 5º, do CPP."},{"id":5558,"materia":"ppen","nivel":3,"enunciado":"Pela Lei 12.850/2013, o delegado e o MP podem acessar, sem autorização judicial, os dados cadastrais do investigado que informem apenas:","opcoes":["Qualificação pessoal, filiação e endereço","O conteúdo das conversas telefônicas gravadas","Os extratos bancários","As mensagens de aplicativos"],"explicacao":"Esses dados são mantidos pela Justiça Eleitoral, empresas telefônicas, bancos e provedores."},{"id":5559,"materia":"ppen","nivel":2,"enunciado":"Convidado a participar da reprodução simulada dos fatos (reconstituição), o investigado:","opcoes":["Não é obrigado a participar, pois ninguém é obrigado a produzir prova contra si","É obrigado a participar, sob pena de prisão preventiva e de responder por desobediência","Só pode recusar com ordem judicial","É obrigado, se o crime for hediondo"],"explicacao":"A reprodução também não pode contrariar a moralidade ou a ordem pública (art. 7º do CPP)."},{"id":5560,"materia":"ppen","nivel":2,"enunciado":"A prisão por mandado judicial pode ser efetuada:","opcoes":["Em qualquer dia e hora, respeitada a inviolabilidade do domicílio","Apenas em dias úteis","Apenas de dia, mesmo que o procurado esteja na rua","Só com a presença do juiz"],"explicacao":"Art. 283, § 2º, do CPP."},{"id":5561,"materia":"ppen","nivel":3,"enunciado":"Terminado o prazo da prisão temporária, o preso deve:","opcoes":["Ser posto em liberdade imediatamente, independentemente de nova ordem do juiz","Aguardar a decisão do juiz sobre a soltura por mais 5 dias, em regra","Continuar preso até a denúncia","Aguardar a ordem do delegado para sair"],"explicacao":"Salvo se já tiver sido decretada a prisão preventiva (art. 2º, § 7º, da Lei 7.960/1989)."},{"id":5562,"materia":"ppen","nivel":3,"enunciado":"Na prisão temporária, o juiz deve decidir sobre a representação do delegado em:","opcoes":["24 horas","5 dias","10 dias","48 horas, depois de ouvir o preso"],"explicacao":"Antes, ouve o Ministério Público (art. 2º, § 2º, da Lei 7.960/1989)."},{"id":5563,"materia":"ppen","nivel":3,"enunciado":"O delegado soube de um homicídio pela imprensa e instaurou o inquérito. Essa notícia do crime é de cognição:","opcoes":["Imediata (espontânea)","Mediata (provocada pela vítima)","Coercitiva","Judicial"],"explicacao":"Na coercitiva, a notícia vem com a apresentação do preso em flagrante."},{"id":5564,"materia":"ppen","nivel":3,"enunciado":"Pelo CPP, terá prioridade na realização do exame de corpo de delito o crime que envolva violência:","opcoes":["Doméstica e familiar contra a mulher ou violência contra criança, adolescente, idoso ou pessoa com deficiência","Apenas contra servidores públicos","Contra o patrimônio","Apenas com uso de arma de fogo ou arma branca contra servidores públicos e autoridades do Estado em serviço"],"explicacao":"Art. 158, parágrafo único, do CPP."},{"id":5565,"materia":"ppen","nivel":3,"enunciado":"Pela Constituição de 1988, a incomunicabilidade do preso prevista no CPP:","opcoes":["Não foi recepcionada","Continua válida por até 3 dias","Vale para crimes hediondos","Depende apenas do delegado"],"explicacao":"Nem no estado de defesa o preso pode ficar incomunicável (art. 136, § 3º, IV, da CF)."},{"id":5566,"materia":"ppen","nivel":3,"enunciado":"Policial militar em serviço mata um civil dolosamente. O julgamento cabe:","opcoes":["Ao Tribunal do Júri, na Justiça comum","À Justiça Militar Estadual","À Justiça Federal","À Justiça Militar Estadual, pois o policial estava em serviço"],"explicacao":"Crimes dolosos contra a vida de civil praticados por militar estadual vão ao Júri."},{"id":5567,"materia":"ppen","nivel":4,"enunciado":"No processo penal, o assistente técnico indicado pelas partes:","opcoes":["Atua após ser admitido pelo juiz e depois de concluídos os exames dos peritos oficiais","Substitui o perito oficial","Atua desde o local do crime, sem autorização, acompanhando os peritos oficiais em todos os exames","Só pode ser indicado pelo delegado"],"explicacao":"Art. 159, § 4º, do CPP."},{"id":5568,"materia":"ppen","nivel":4,"enunciado":"Segundo o STJ, a quebra da cadeia de custódia de um vestígio:","opcoes":["Não gera nulidade automática; o juiz avalia a confiabilidade da prova","Anula todo o processo, sempre, e torna ilícitas todas as demais provas","Torna o réu automaticamente inocente","É irrelevante e não pode ser alegada"],"explicacao":"A prova pode perder valor conforme o caso concreto."},{"id":5569,"materia":"leg","nivel":0,"enunciado":"Pela Lei 8.072/1990, o estupro é crime:","opcoes":["Hediondo","De menor potencial ofensivo","Contravenção penal","Culposo"],"explicacao":"O estupro de vulnerável também é hediondo."},{"id":5570,"materia":"leg","nivel":1,"enunciado":"Pessoa flagrada andando na rua com revólver de uso permitido, sem autorização de porte, comete:","opcoes":["Porte ilegal de arma de fogo de uso permitido","Posse irregular de arma de fogo","Disparo de arma de fogo","Nenhum crime, se a arma for registrada no nome de um parente"],"explicacao":"Art. 14 do Estatuto do Desarmamento."},{"id":5571,"materia":"leg","nivel":2,"enunciado":"Pela Lei 13.431/2017, a oitiva de criança ou adolescente vítima de violência perante autoridade policial ou judiciária é chamada de:","opcoes":["Depoimento especial","Escuta especializada","Acareação","Reconhecimento de pessoas"],"explicacao":"A escuta especializada é a entrevista feita pela rede de proteção, como saúde e assistência social."},{"id":5572,"materia":"leg","nivel":2,"enunciado":"Quem submete pessoa presa sob sua guarda a intenso sofrimento físico ou mental, como forma de castigo pessoal, comete:","opcoes":["Tortura-castigo","Maus-tratos apenas","Lesão corporal leve","Abuso de autoridade apenas"],"explicacao":"Art. 1º, II, da Lei 9.455/1997."},{"id":5573,"materia":"leg","nivel":3,"enunciado":"Pelo Estatuto do Desarmamento, portar arma de fogo com numeração raspada:","opcoes":["Recebe a mesma pena do crime envolvendo arma de uso restrito","É apenas infração administrativa","Tem a mesma pena do porte de arma de uso permitido, sem nenhum agravamento","Não é crime se a arma estiver desmuniciada"],"explicacao":"Art. 16, § 1º, IV, da Lei 10.826/2003."},{"id":5574,"materia":"leg","nivel":2,"enunciado":"Policial que expõe o preso à curiosidade pública, obrigando-o a se exibir para a imprensa, comete:","opcoes":["Crime de abuso de autoridade","Apenas falta ética","Nenhum ilícito","Crime de tortura psicológica, sempre"],"explicacao":"Art. 13 da Lei 13.869/2019."},{"id":5575,"materia":"leg","nivel":2,"enunciado":"Pela Lei 9.099/1995, a lesão corporal leve e a lesão culposa dependem de:","opcoes":["Representação da vítima","Requisição do ministro da Justiça","Queixa-crime","Nada, são de ação pública incondicionada"],"explicacao":"Art. 88 da Lei 9.099/1995; a regra não vale para violência doméstica contra a mulher."},{"id":5576,"materia":"leg","nivel":2,"enunciado":"Adulto que pratica furto junto com um adolescente de 15 anos também comete corrupção de menores. Segundo a Súmula 500 do STJ, esse crime:","opcoes":["É formal e dispensa prova da efetiva corrupção do adolescente","Exige prova de que o adolescente foi corrompido","Não existe mais no ECA","Só existe se o adolescente nunca tiver cometido ato infracional antes"],"explicacao":"Art. 244-B do ECA."},{"id":5577,"materia":"leg","nivel":3,"enunciado":"Pela Lei 12.850/2013, quem impede ou embaraça a investigação de infração penal que envolva organização criminosa:","opcoes":["Recebe as mesmas penas de quem integra a organização","Comete apenas o crime de desobediência à ordem policial","Não comete crime","Comete contravenção penal"],"explicacao":"Art. 2º, § 1º, da Lei 12.850/2013."},{"id":5578,"materia":"leg","nivel":3,"enunciado":"Para a prisão em flagrante por tráfico, basta:","opcoes":["O laudo de constatação provisório da natureza da droga","O laudo definitivo, sempre","A confissão do preso","O depoimento de um policial experiente, sem nenhum tipo de laudo"],"explicacao":"O laudo definitivo é necessário para a condenação."},{"id":5579,"materia":"leg","nivel":3,"enunciado":"O policial que deixa de se identificar ao preso no momento da captura comete:","opcoes":["Crime de abuso de autoridade","Apenas infração disciplinar leve","Crime de tortura","Nenhum ilícito, pois a farda já identifica o policial"],"explicacao":"Art. 16 da Lei 13.869/2019."},{"id":5580,"materia":"leg","nivel":3,"enunciado":"Na Lei Antiterrorismo (Lei 13.260/2016), os atos preparatórios de terrorismo, com o propósito inequívoco de consumá-lo:","opcoes":["São punidos, com pena reduzida","Nunca são punidos","São punidos como contravenção","Só são punidos se houver mortes"],"explicacao":"É exceção à regra de que atos preparatórios não são puníveis."},{"id":5581,"materia":"leg","nivel":3,"enunciado":"Pela Lei 12.037/2009, a coleta de perfil genético na identificação criminal, quando essencial às investigações:","opcoes":["Depende de autorização judicial","Pode ser feita por ordem do delegado, sempre","É proibida no Brasil","Depende só do consentimento da vítima"],"explicacao":"Os dados ficam em banco de perfis genéticos sigiloso."},{"id":5582,"materia":"leg","nivel":2,"enunciado":"Pela Lei 13.431/2017, a escuta especializada de criança ou adolescente vítima de violência é:","opcoes":["Entrevista feita por órgão da rede de proteção, limitada ao necessário para o cuidado","Depoimento prestado ao juiz em audiência, com a presença do acusado e de seu advogado","Interrogatório feito pelo delegado","Acareação com o agressor"],"explicacao":"Busca evitar que a vítima repita a história várias vezes."},{"id":5583,"materia":"leg","nivel":4,"enunciado":"Segundo o STJ, após o cancelamento da Súmula 174, o roubo praticado com arma de brinquedo:","opcoes":["Não tem a pena aumentada pelo emprego de arma","Tem a pena aumentada em 2/3","Tem a pena aplicada em dobro","Tem a pena aumentada em 2/3, como a arma verdadeira"],"explicacao":"A arma de brinquedo serve para a grave ameaça, mas não gera a majorante."},{"id":5584,"materia":"const","nivel":1,"enunciado":"Um candidato eliminado de concurso por ato ilegal, com prova documental de seu direito, deve usar:","opcoes":["Mandado de segurança","Habeas corpus","Habeas data","Ação popular, por se tratar de interesse coletivo"],"explicacao":"O MS protege direito líquido e certo não amparado por HC ou HD."},{"id":5585,"materia":"const","nivel":1,"enunciado":"Sobre o habeas corpus, é correto afirmar que:","opcoes":["É gratuito e pode ser impetrado por qualquer pessoa, mesmo sem advogado","Exige advogado constituído e o pagamento prévio de custas","Só pode ser impetrado pelo próprio preso","Serve para corrigir dados em banco público"],"explicacao":"Protege a liberdade de locomoção."},{"id":5586,"materia":"const","nivel":2,"enunciado":"É brasileiro nato o nascido no exterior, filho de pai ou mãe brasileira, que:","opcoes":["Seja registrado em repartição brasileira competente","Apenas tenha passaporte estrangeiro","Seja maior de 30 anos","Tenha morado 1 ano no Brasil, mesmo sem registro em repartição"],"explicacao":"Também é nato se vier a residir no Brasil e optar pela nacionalidade após a maioridade."},{"id":5587,"materia":"const","nivel":1,"enunciado":"Pela Constituição, entre as penas proibidas no Brasil estão:","opcoes":["Prisão perpétua, trabalhos forçados, banimento e penas cruéis","Multa, prestação de serviços à comunidade e perda de bens","Privação da liberdade","Suspensão de direitos"],"explicacao":"A pena de morte só é admitida em caso de guerra declarada."},{"id":5588,"materia":"const","nivel":2,"enunciado":"A interceptação telefônica, pela Constituição, só pode ser autorizada:","opcoes":["Por ordem judicial, para investigação criminal ou instrução processual penal","Pelo delegado de polícia, em qualquer investigação, por despacho fundamentado","Por CPI, para qualquer finalidade","Pelo Ministério Público, sem ordem judicial"],"explicacao":"Art. 5º, XII, da Constituição Federal."},{"id":5589,"materia":"const","nivel":4,"enunciado":"Durante o estado de defesa, a prisão por crime contra o Estado:","opcoes":["Não pode passar de 10 dias, salvo autorização do Judiciário","Pode durar indefinidamente","Dispensa comunicação ao juiz, por ser medida de exceção","Permite deixar o preso incomunicável"],"explicacao":"Art. 136, § 3º, III, da Constituição Federal."},{"id":5590,"materia":"const","nivel":2,"enunciado":"Pela Constituição, a obrigação de reparar o dano causado pelo crime:","opcoes":["Pode ser estendida aos sucessores, até o limite do patrimônio transferido","Desaparece com a morte do condenado","Passa integralmente aos filhos do condenado, mesmo sem herança","Recai sobre o Estado"],"explicacao":"A pena em si não passa da pessoa do condenado."},{"id":5591,"materia":"const","nivel":3,"enunciado":"Pela Constituição, não cabe habeas corpus em relação ao mérito de:","opcoes":["Punições disciplinares militares","Prisão em flagrante","Prisão preventiva decretada por juiz","Prisão temporária"],"explicacao":"O STF admite HC para discutir a legalidade da punição, mas não o mérito."},{"id":5592,"materia":"const","nivel":3,"enunciado":"Uma CPI, segundo o STF, pode:","opcoes":["Quebrar sigilo bancário e fiscal, mas não decretar interceptação telefônica","Decretar interceptação telefônica e prisão preventiva dos investigados","Julgar e condenar investigados","Determinar busca domiciliar sem ordem judicial"],"explicacao":"A interceptação depende de ordem judicial (reserva de jurisdição)."},{"id":5593,"materia":"const","nivel":3,"enunciado":"Pela Constituição, cabe à Polícia Federal, entre outras funções:","opcoes":["Exercer, com exclusividade, as funções de polícia judiciária da União","Patrulhar ostensivamente as rodovias e ferrovias federais de todo o país","Fazer o policiamento ostensivo nos estados","Julgar crimes federais"],"explicacao":"O patrulhamento das rodovias federais cabe à Polícia Rodoviária Federal."},{"id":5594,"materia":"adm","nivel":1,"enunciado":"Placa de obra pública com nome, foto e slogan do prefeito para promovê-lo viola, principalmente, o princípio da:","opcoes":["Impessoalidade","Eficiência","Continuidade do serviço","Autotutela"],"explicacao":"Art. 37, § 1º, da Constituição Federal."},{"id":5595,"materia":"adm","nivel":1,"enunciado":"Integram a Administração Pública indireta:","opcoes":["Autarquias, fundações públicas, empresas públicas e sociedades de economia mista","Ministérios e secretarias","Câmaras municipais","Delegacias de polícia e secretarias estaduais de segurança"],"explicacao":"Os ministérios e secretarias são órgãos da Administração direta."},{"id":5596,"materia":"adm","nivel":3,"enunciado":"Os atos de quem exerce irregularmente uma função pública, mas parece regularmente investido (agente de fato putativo):","opcoes":["São considerados válidos perante terceiros de boa-fé","São sempre inexistentes","Geram responsabilidade só do cidadão que foi atendido","São válidos só com ordem judicial"],"explicacao":"Aplicam-se a teoria da aparência e a proteção da boa-fé."},{"id":5597,"materia":"adm","nivel":2,"enunciado":"O STF considera legítima a divulgação, na internet, da remuneração dos servidores com seus nomes, com base no princípio da:","opcoes":["Publicidade","Impessoalidade","Autotutela","Especialidade"],"explicacao":"Também é uma exigência da Lei de Acesso à Informação."},{"id":5598,"materia":"adm","nivel":2,"enunciado":"Pela Lei de Acesso à Informação, o prazo para o órgão público responder ao pedido, quando não puder dar acesso imediato, é de até:","opcoes":["20 dias, prorrogáveis por mais 10","5 dias úteis, sem prorrogação","60 dias","1 ano"],"explicacao":"A prorrogação deve ser justificada ao requerente."},{"id":5599,"materia":"adm","nivel":2,"enunciado":"A diferença básica entre empresa pública e sociedade de economia mista é que:","opcoes":["Na empresa pública o capital é todo público; na mista, há capital privado com controle estatal","Só a sociedade de economia mista é de direito privado","Só a empresa pública pode explorar atividade econômica, e a mista só presta serviço público","Não há nenhuma diferença"],"explicacao":"A sociedade de economia mista é sempre uma sociedade anônima."},{"id":5600,"materia":"adm","nivel":2,"enunciado":"A Polícia Civil cria uma nova delegacia especializada dentro da sua própria estrutura. Isso é:","opcoes":["Desconcentração","Descentralização","Delegação a particular","Privatização"],"explicacao":"Na descentralização, a atividade passa a outra pessoa jurídica."},{"id":5601,"materia":"adm","nivel":2,"enunciado":"A Lei 14.735/2023 instituiu:","opcoes":["A Lei Orgânica Nacional das Polícias Civis","O Estatuto do Desarmamento","A Lei de Abuso de Autoridade","O Sistema Único de Segurança Pública (Susp) e a Força Nacional"],"explicacao":"Ela traz normas gerais de funcionamento das polícias civis dos estados e do DF."},{"id":5602,"materia":"adm","nivel":2,"enunciado":"Servidor recebe de uma empresa interessada em contrato um carro de presente. É ato de improbidade que:","opcoes":["Importa enriquecimento ilícito","Atenta apenas contra princípios","Não é improbidade","Só gera multa de trânsito"],"explicacao":"Art. 9º da Lei 8.429/1992."},{"id":5603,"materia":"adm","nivel":2,"enunciado":"São causas que excluem a responsabilidade civil do Estado:","opcoes":["Culpa exclusiva da vítima e caso fortuito ou força maior","Culpa leve do agente público","Dano causado em serviço","Prejuízo pequeno, abaixo de um salário mínimo, causado pelo agente"],"explicacao":"Se a culpa da vítima for apenas concorrente, a indenização é reduzida."},{"id":5604,"materia":"adm","nivel":3,"enunciado":"Pela Lei 14.133/2021, na contratação direta por emergência, o contrato pode durar no máximo:","opcoes":["1 ano, vedada a prorrogação","5 anos, prorrogáveis","180 dias, prorrogáveis por mais 180","10 anos"],"explicacao":"Também é proibido recontratar a mesma empresa com base na mesma emergência."},{"id":5605,"materia":"adm","nivel":3,"enunciado":"O servidor que deixa de praticar ato que a lei lhe impõe, prejudicando o cidadão, pratica abuso de poder na forma:","opcoes":["Omissiva","Comissiva por excesso","Comissiva por desvio de finalidade","Delegada"],"explicacao":"O abuso de poder pode ocorrer por ação ou por omissão."},{"id":5606,"materia":"port","nivel":1,"enunciado":"Segundo a norma-padrão, está correta a frase:","opcoes":["Eles têm muitas provas contra o suspeito.","Eles tem muitas provas contra o suspeito.","Eles teem muitas provas contra o suspeito.","Eles tém muitas provas contra o suspeito."],"explicacao":"No plural, “ter” e “vir” recebem acento circunflexo: têm, vêm."},{"id":5607,"materia":"port","nivel":1,"enunciado":"Complete: “O perigo era ___, e o ___ delegado tomou providências.”","opcoes":["iminente / eminente","eminente / iminente","iminente / iminente","eminente / eminente"],"explicacao":"Iminente = prestes a acontecer; eminente = ilustre, importante."},{"id":5608,"materia":"port","nivel":1,"enunciado":"Complete corretamente: “O suspeito agiu de ___ fé e se comportou ___ no depoimento.”","opcoes":["má / mal","mau / mal","má / mau","mal / mau"],"explicacao":"Mau/má são adjetivos (opostos de bom/boa); mal é advérbio (oposto de bem)."},{"id":5609,"materia":"port","nivel":1,"enunciado":"Nas frases “O delegado ratificou a decisão” e “O escrivão retificou o termo”, os verbos significam, respectivamente:","opcoes":["Confirmar e corrigir","Corrigir e confirmar","Anular e confirmar","Confirmar e anular"],"explicacao":"Ratificar = confirmar; retificar = corrigir."},{"id":5610,"materia":"port","nivel":2,"enunciado":"Está de acordo com a norma-padrão:","opcoes":["Aonde você vai depois do plantão?","Aonde você está agora, depois do plantão?","Onde você vai depois do plantão?","Aonde fica a delegacia?"],"explicacao":"“Aonde” indica movimento (ir a); “onde” indica lugar fixo."},{"id":5611,"materia":"port","nivel":2,"enunciado":"Em “O juiz deferiu o pedido” e “A audiência foi diferida”, os verbos significam, respectivamente:","opcoes":["Concedeu e adiada","Adiou e concedida","Negou e cancelada","Concedeu e antecipada"],"explicacao":"Deferir = conceder, atender; diferir = adiar."},{"id":5612,"materia":"port","nivel":2,"enunciado":"Está correta a concordância em:","opcoes":["Seguem anexas as cópias do inquérito.","Segue anexo as cópias do inquérito policial.","Seguem anexo as cópias do inquérito.","Segue anexas as cópias do inquérito."],"explicacao":"“Anexo” é adjetivo e concorda com o substantivo."},{"id":5613,"materia":"port","nivel":2,"enunciado":"Está correto o uso do pronome relativo em:","opcoes":["O policial cujo carro foi roubado registrou a ocorrência.","O policial cujo o carro foi roubado registrou a ocorrência.","O policial que o carro foi roubado registrou a ocorrência.","O policial onde o carro foi roubado registrou a ocorrência."],"explicacao":"“Cujo” indica posse e não admite artigo depois dele."},{"id":5614,"materia":"port","nivel":3,"enunciado":"Complete: “O delegado falou ___ do caso; ___ dez dias ele já sabia de tudo.”","opcoes":["acerca / Há cerca de","a cerca / Acerca de","há cerca / A cerca de","acerca / A cerca de"],"explicacao":"Acerca de = sobre; há cerca de = faz aproximadamente."},{"id":5615,"materia":"port","nivel":4,"enunciado":"Está correta a concordância em:","opcoes":["Investigam-se os casos de desaparecimento.","Investiga-se os casos de desaparecimento.","Investigam-se o caso de desaparecimento.","Investiga-se de os casos de desaparecimento."],"explicacao":"Na voz passiva sintética, o verbo concorda com o sujeito paciente: os casos são investigados."},{"id":5616,"materia":"rl","nivel":0,"enunciado":"Na sequência 2, 6, 18, 54, ..., o próximo termo é:","opcoes":["162","108","72","216"],"explicacao":"Cada termo é o anterior multiplicado por 3."},{"id":5617,"materia":"rl","nivel":3,"enunciado":"Qual o menor número de pessoas que garante que pelo menos duas nasceram no mesmo mês?","opcoes":["13","12","24","2"],"explicacao":"Princípio da casa dos pombos: 12 meses + 1."},{"id":5618,"materia":"rl","nivel":1,"enunciado":"Se 4 investigadores fazem um levantamento em 6 dias, 8 investigadores, no mesmo ritmo, farão em:","opcoes":["3 dias","12 dias","6 dias","2 dias"],"explicacao":"Mais investigadores, menos dias: grandezas inversamente proporcionais."},{"id":5619,"materia":"rl","nivel":2,"enunciado":"A negação de “Nenhum policial é corrupto” é:","opcoes":["Algum policial é corrupto","Todo policial é corrupto","Nenhum policial é honesto","Todo policial é honesto"],"explicacao":"A negação de “nenhum” é “algum”."},{"id":5620,"materia":"rl","nivel":2,"enunciado":"A proposição “O réu será solto se, e somente se, pagar a fiança” é falsa quando:","opcoes":["Uma parte é verdadeira e a outra é falsa","As duas partes são verdadeiras","As duas partes são falsas","Sempre que a fiança for paga pelo próprio réu"],"explicacao":"O bicondicional é verdadeiro só quando as duas partes têm o mesmo valor."},{"id":5621,"materia":"rl","nivel":2,"enunciado":"Um capital de R$ 1.000 aplicado a juros simples de 2% ao mês por 5 meses rende de juros:","opcoes":["R$ 100","R$ 10","R$ 1.100","R$ 200"],"explicacao":"J = 1.000 × 0,02 × 5 = 100."},{"id":5622,"materia":"inf","nivel":1,"enunciado":"No Google Chrome, o atalho Ctrl + Shift + N abre:","opcoes":["Uma janela anônima","O histórico","Uma nova aba comum","As configurações"],"explicacao":"Ctrl + T abre uma nova aba comum."},{"id":5623,"materia":"inf","nivel":2,"enunciado":"No Microsoft Word, o atalho Ctrl + K serve para:","opcoes":["Inserir um hiperlink","Salvar o documento","Imprimir","Inserir uma tabela no documento"],"explicacao":"Também funciona em outros programas do Office."},{"id":5624,"materia":"inf","nivel":2,"enunciado":"O ataque que tira um site do ar sobrecarregando-o com acessos simultâneos de muitas máquinas é o:","opcoes":["DDoS (negação de serviço distribuída)","Phishing","Backup em nuvem","Spam"],"explicacao":"Muitas vezes usa uma botnet de computadores infectados."},{"id":5625,"materia":"inf","nivel":2,"enunciado":"No Excel, a fórmula =CONT.SE(A1:A10;\">5\") retorna:","opcoes":["A quantidade de células de A1 a A10 com valor maior que 5","A soma de todos os valores maiores que 5 no intervalo","A média dos valores maiores que 5","O maior valor do intervalo"],"explicacao":"Para somar com condição, usa-se SOMASE."},{"id":5626,"materia":"inf","nivel":3,"enunciado":"Um golpe que usa QR Code falso, colado sobre o verdadeiro, para levar a vítima a um site malicioso ou a pagar a pessoa errada é uma forma de:","opcoes":["Phishing (quishing)","Backup","Firewall","Criptografia"],"explicacao":"Antes de pagar, confira o nome do recebedor no aplicativo do banco."},{"id":5627,"materia":"inf","nivel":3,"enunciado":"No Excel, ao arrastar a alça de preenchimento de uma célula com “jan”, as células seguintes recebem:","opcoes":["fev, mar, abr...","jan, jan, jan... sempre","1, 2, 3...","Nada, pois não é número"],"explicacao":"O Excel reconhece listas como meses e dias da semana."},{"id":5628,"materia":"dh","nivel":3,"enunciado":"O Código de Conduta para os Funcionários Responsáveis pela Aplicação da Lei foi adotado pela ONU em:","opcoes":["1979","1948","2015","1990"],"explicacao":"Prevê o uso da força só quando estritamente necessário."},{"id":5629,"materia":"dh","nivel":3,"enunciado":"Os Princípios Básicos sobre o Uso da Força e Armas de Fogo pelos Funcionários Responsáveis pela Aplicação da Lei são da ONU, de:","opcoes":["1990","1979","1969","2006"],"explicacao":"Armas de fogo só em último caso, para proteger a vida."},{"id":5630,"materia":"dh","nivel":2,"enunciado":"A Convenção Americana de Direitos Humanos garante ao acusado, entre outros direitos:","opcoes":["Recorrer da sentença a juiz ou tribunal superior","Escolher o juiz do processo","Não comparecer a nenhum ato","Ser julgado só por júri popular, em qualquer crime"],"explicacao":"É a garantia do duplo grau de jurisdição."},{"id":5631,"materia":"dh","nivel":4,"enunciado":"As Regras de Pequim, da ONU, tratam:","opcoes":["Da administração da justiça da infância e da juventude","Do tratamento de mulheres presas e das mães encarceradas","Do uso da força policial","Dos refugiados"],"explicacao":"As Regras de Bangkok tratam das mulheres presas."},{"id":5632,"materia":"dh","nivel":4,"enunciado":"O Protocolo de Istambul, da ONU, é um manual para:","opcoes":["Investigar e documentar casos de tortura","Regular o comércio internacional entre países da Europa e da Ásia","Proteger o meio ambiente","Organizar eleições"],"explicacao":"Orienta médicos, peritos e juristas na apuração da tortura."},{"id":5633,"materia":"est","nivel":1,"enunciado":"No conjunto 3, 9, 12 e 5, a amplitude é:","opcoes":["9","12","3","29"],"explicacao":"Amplitude = maior valor − menor valor = 12 − 3."},{"id":5634,"materia":"est","nivel":2,"enunciado":"A mediana dos valores 4, 8, 6 e 2 é:","opcoes":["5","6","4","20"],"explicacao":"Em ordem: 2, 4, 6, 8; com número par de dados, a mediana é a média dos dois centrais: (4 + 6) ÷ 2."},{"id":5635,"materia":"est","nivel":2,"enunciado":"Um candidato tirou 6 numa prova de peso 2 e 9 numa prova de peso 1. A média ponderada é:","opcoes":["7","7,5","8","15"],"explicacao":"(6 × 2 + 9 × 1) ÷ 3 = 21 ÷ 3 = 7."},{"id":5636,"materia":"cont","nivel":2,"enunciado":"Na Demonstração do Resultado (DRE), a receita líquida é obtida:","opcoes":["Subtraindo da receita bruta as devoluções, os abatimentos e os impostos sobre vendas","Somando todas as despesas","Subtraindo o custo das mercadorias vendidas do lucro líquido do exercício anterior, ajustado pelos impostos","Somando o passivo ao ativo"],"explicacao":"Depois, subtrai-se o custo para chegar ao lucro bruto."},{"id":5637,"materia":"cont","nivel":2,"enunciado":"Os sócios integralizam capital em dinheiro na empresa. Esse fato:","opcoes":["Aumenta o ativo e o patrimônio líquido","Aumenta o passivo","Reduz o ativo","Aumenta o passivo e o capital social"],"explicacao":"Entra dinheiro no caixa e aumenta o capital social."},{"id":5638,"materia":"cont","nivel":3,"enunciado":"Pelo método das partidas dobradas, as contas do ativo aumentam por:","opcoes":["Débito","Crédito","Estorno","Provisão"],"explicacao":"Passivo e patrimônio líquido aumentam por crédito."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('pen','ppen','leg','const','adm','port','rl','inf','dh','est','cont') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
